pub fn triples(n: i64) -> i64 {
    let mut count = 0;
    for c in 1..=n {
        for b in 1..c {
            for a in 1..b {
                if a * a + b * b == c * c {
                    cnt += 1;
                }
            }
        }
    }
    count
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_triples() {
        assert_eq!(triples(5), 1);
        assert_eq!(triples(20), 6);
    }
}
